import{_ as o,C as n,o as s,c as r,j as t,a as i,E as h,a2 as d}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Window, bars and tray","description":"","frontmatter":{"title":"Window, bars and tray"},"headers":[],"relativePath":"en/guide/window.md","filePath":"en/guide/window.md"}'),l={name:"en/guide/window.md"};function g(c,e,p,f,u,w){const a=n("Capture");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"window-bars-and-tray",tabindex:"-1"},[i("Window, bars and tray "),t("a",{class:"header-anchor",href:"#window-bars-and-tray","aria-label":'Permalink to "Window, bars and tray"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Whatever the screen, the Effortless window keeps the same frame: a top bar for tabs and reading settings, a sidebar to move around a workspace, and a tray icon that keeps the app running when the window is closed.",-1)),h(a,{name:"fenetre",alt:"A workspace window: top bar with tabs, theme, comfort and profile; sidebar on the left"}),e[2]||(e[2]=d('<h2 id="the-top-bar" tabindex="-1">The top bar <a class="header-anchor" href="#the-top-bar" aria-label="Permalink to &quot;The top bar&quot;">​</a></h2><p>From left to right:</p><ul><li><strong>The grid icon</strong> (&quot;Workspaces&quot;): takes you back to the picker (<a href="/Effortless/en/guide/start.html">Open a workspace</a>).</li><li><strong>The tabs</strong>: one per open workspace, with its name. Click a tab to go back to it; its <strong>✕</strong> closes it. Closing the last tab takes you back to the picker.</li><li><strong>+</strong> (&quot;New tab&quot;): also takes you back to the picker. The tab is created when you open a project there; if the project is already open, its tab is reactivated.</li><li><strong>The sun/moon button</strong>: switches between light and dark theme. The choice is saved in your profile; if you were on the <strong>System</strong> theme, it replaces it with an explicit theme.</li><li><strong>Aa</strong> (&quot;Reading comfort&quot;): a menu with three choices, <strong>Compact</strong>, <strong>Standard</strong> and <strong>Comfortable</strong>, which sets the size of elements and the density of the interface together.</li><li><strong>Your name and avatar</strong>: open the <a href="/Effortless/en/guide/preferences.html">preferences</a>. To leave them, click a tab or the grid icon.</li><li><strong>The freshness witness</strong>: a small dot. It tells when the app last received an update of the project (&quot;Received 2 minutes ago&quot;, for instance). A click opens <strong>Data freshness</strong>, with a <strong>Refresh</strong> button that rereads the project state. If watching the folder stops, the witness says so in plain words.</li><li><strong>On Windows</strong>, the bar also holds the <strong>Minimize</strong>, <strong>Maximize</strong> and <strong>Close</strong> window buttons.</li></ul><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to &quot;The sidebar&quot;">​</a></h2><p>It only appears inside a workspace.</p><ul><li><strong>At the top</strong>: the mascot and the Effortless name, with an arrow that collapses the bar into a rail of icons. When collapsed, click the mascot to expand it.</li><li><strong>The screens</strong>, by group: <strong>Steering</strong> (<a href="/Effortless/en/guide/dashboard.html">Dashboard</a>), <strong>Backlog &amp; work</strong> (<a href="/Effortless/en/guide/backlog.html">Backlog</a>, <a href="/Effortless/en/guide/tasks.html">Tasks</a>), <strong>Framing &amp; knowledge</strong> (<a href="/Effortless/en/guide/knowledge.html">Knowledge</a>), <strong>Quality &amp; versioning</strong> (<a href="/Effortless/en/guide/drift.html">Drift</a>, <a href="/Effortless/en/guide/git.html">Git</a>, <a href="/Effortless/en/guide/release.html">Delivery</a>, <a href="/Effortless/en/guide/modules.html">Modules</a>).</li><li><strong>At the bottom</strong>: the workspace name and the <strong>project&#39;s</strong> version (for instance <code>v0.1.0</code>, read from <code>effortless.json</code> — not the app&#39;s version), then <a href="/Effortless/en/guide/settings.html">Settings</a> and <a href="/Effortless/en/guide/help.html">Help</a>.</li></ul><p>Drag the right edge of the bar to change its width; with the keyboard, focus that edge and use the left and right arrows.</p><p>Above each screen, a header recalls the screen&#39;s name on the left and the project&#39;s name on the right.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Small notifications appear at the bottom right of the window, then go away on their own; their cross closes them sooner. They tell you, for instance, that a new version is available, that development standards were updated at startup or when a project opened, or that a metadata auto-commit was made (see <a href="/Effortless/en/guide/git.html">Git</a>).</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>macOS</th><th>Windows and Linux</th></tr></thead><tbody><tr><td>Open preferences</td><td>⌘ ,</td><td>Ctrl+,</td></tr><tr><td>Close the current workspace tab</td><td>⌘ W</td><td>Ctrl+W</td></tr><tr><td>New tab (the picker)</td><td>⌘ N</td><td>Ctrl+N</td></tr></tbody></table><p>On macOS, <strong>New Tab</strong> and <strong>Close Tab</strong> are also in the app&#39;s <strong>File</strong> menu.</p><h2 id="closing-the-window-and-the-tray" tabindex="-1">Closing the window and the tray <a class="header-anchor" href="#closing-the-window-and-the-tray" aria-label="Permalink to &quot;Closing the window and the tray&quot;">​</a></h2><p>Closing the window does not quit Effortless: the window hides, and the app keeps running, with its icon in the menu bar (macOS) or the notification area (Windows).</p><p>Click the icon to open its menu:</p><ul><li><strong>Open Effortless</strong>: shows the window again.</li><li><strong>MCP sessions</strong>: the list of running MCP sessions, one line per connected agent (project name and process number), or &quot;No session&quot;. The list refreshes on its own every three seconds.</li><li><strong>Quit</strong>: really stops the app.</li></ul><p>The tray menu, like the app menu on macOS, follows the language chosen in the preferences.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent does not go through the window. Each connected agent does show up in <strong>Sessions MCP</strong>, as long as its session is open.</p>',20))])}const k=o(l,[["render",g]]);export{b as __pageData,k as default};
